<?php if ($pages > 1): ?><nav class="pagination" aria-label="<?= e(t('Pagination')) ?>"><span><?= e(t('Page')) ?> <?= $page ?> / <?= $pages ?></span><div><?php if ($page > 1): ?><a class="button" href="<?= e(page_link(strtok(current_route(),'?'),['page' => $page-1])) ?>"><?= e(t('Previous')) ?></a><?php endif ?><?php if ($page < $pages): ?><a class="button" href="<?= e(page_link(strtok(current_route(),'?'),['page' => $page+1])) ?>"><?= e(t('Next')) ?></a><?php endif ?></div></nav><?php endif ?>
